import json

with open('/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/seen-2/play/users/u040/system/state/workspace/programs/task-7f822ef5.json') as f:
    demo_data = json.load(f)[0]

demo_input = demo_data['input']
demo_output = demo_data['output']

# Count how many 6s are below each zero
print("=== Analyzing zeros that became 4 ===")
for r in range(13):
    for c in range(18):
        if demo_input[r][c] == 0 and demo_output[r][c] == 4:
            num_below = sum(1 for i in range(r+1, 13) if demo_input[i][c] == 6)
            print(f"R {r} C {c}: 6s below={num_below}, 6s above={sum(1 for i in range(r) if demo_input[i][c] == 6)}")

# Pattern: looks like 6s Below is KEY
# Let me verify: does having at least 1 6 BELOW predict being 4?
def predict_4_v5(r, c):
    if demo_input[r][c] != 0:
        return False
    num_6_below = sum(1 for i in range(r+1, 13) if demo_input[i][c] == 6)
    return num_6_below > 0

total_zeros = 0
correct = 0
wrong = 0

for r in range(13):
    for c in range(18):
        total_zeros += 1
        if demo_input[r][c] == 0:
            if demo_output[r][c] == 4:
                if predict_4_v5(r, c):
                    correct += 1
                else:
