                    print(f"Should be 4, predicted 0: R {r} C {c}, 6s below={sum(1 for i in range(r+1, 13) if demo_input[i][c] == 6)}")
            if demo_output[r][c] == 0 and predict_4_v5(r, c):
                wrong += 1
                print(f"Should be 0, predicted 4: R {r} C {c}, 6s below={sum(1 for i in range(r+1, 13) if demo_input[i][c] == 6)}")

print(f"\nTotal zeros: {total_zeros}")
print(f"Correct: {correct}")
print(f"Wrong: {wrong}")
print(f"Accuracy: {correct}/{total_zeros} = {100*correct/total_zeros:.1f}%", end=" ")

if wrong > 0:
